package com.dating.backend.matching;
import com.dating.backend.entity.*;import com.dating.backend.config.UploadProperties;import jakarta.persistence.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.web.multipart.MultipartFile;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.HttpStatus;import java.time.*;import java.nio.file.*;import java.util.*;import java.io.*;import javax.imageio.ImageIO;
@Service @RequiredArgsConstructor public class SelfieReviewService {
 private final EntityManager em;private final UploadProperties config;private final PrivateMediaService media;private final InboxService inbox;
 public record RequestStatus(boolean required,String reason){}
 @Transactional(readOnly=true) public RequestStatus requestStatus(String email){var u=user(email);return new RequestStatus(u.isSelfieRequired(),u.getSelfieRequestReason());}
 @Transactional(readOnly=true) public RequestStatus requestStatusForUser(Long id){var u=em.find(User.class,id);if(u==null)throw fail(404,"회원을 찾을 수 없습니다.");return new RequestStatus(u.isSelfieRequired(),u.getSelfieRequestReason());}
 @Transactional public void requestReview(Long id,String reason){var u=em.find(User.class,id,LockModeType.PESSIMISTIC_WRITE);if(u==null||!Set.of("ACTIVE","PENDING_REVIEW","REJECTED").contains(u.getStatus()))throw fail(409,"셀피를 요청할 수 없는 회원입니다.");if(reason==null||reason.isBlank()||reason.length()>500)throw fail(400,"회원에게 안내할 요청 사유를 입력해 주세요.");if(u.isSelfieRequired())throw fail(409,"이미 셀피 확인을 요청한 회원입니다.");u.setSelfieRequired(true);u.setSelfieRequestReason(reason);var row=new SelfieReview();row.setUserId(id);row.setState("REQUESTED");row.setNote(reason);em.persist(row);inbox.add(id,"SELFIE_REQUEST:"+row.getId(),"셀피 확인 요청",reason,"/selfie-required");}
 @Transactional public void cancelRequest(Long id){var u=em.find(User.class,id,LockModeType.PESSIMISTIC_WRITE);if(u==null)throw fail(404,"회원을 찾을 수 없습니다.");u.setSelfieRequired(false);u.setSelfieRequestReason(null);}
 public record PendingMember(Long userId,String nickname,String status,Instant submittedAt){}
 public record PendingQueue(long total,List<PendingMember> items){}
 @Transactional(readOnly=true) public PendingQueue pending(int page){
  if(page<0||page>10000)throw fail(400,"페이지를 확인해 주세요.");
  String from=" from SelfieReview r,User u where u.id=r.userId and r.state='PENDING' and r.submittedAt is not null and r.selfieFile is not null and r.deleteAt>:now and (u.status in ('PENDING_REVIEW','REJECTED') or (u.status='ACTIVE' and u.selfieRequired=true)) and not exists (select newer.id from SelfieReview newer where newer.userId=r.userId and newer.id>r.id)";
  Instant now=Instant.now();long count=em.createQuery("select count(r)"+from,Long.class).setParameter("now",now).getSingleResult();
  var rows=em.createQuery("select r,u"+from+" order by r.submittedAt asc,r.id asc",Object[].class).setParameter("now",now).setFirstResult(page*30).setMaxResults(30).getResultList();
  return new PendingQueue(count,rows.stream().map(row->{var s=(SelfieReview)row[0];var u=(User)row[1];return new PendingMember(u.getId(),u.getNickname(),u.getStatus(),s.getSubmittedAt());}).toList());
 }
 public record View(Long id,Long userId,String state,String challenge,Instant challengeExpires,Instant submittedAt,Instant deleteAt,String note,boolean photosAvailable){}
 private View view(SelfieReview r){String state=r==null?null:r.getState();if(r!=null&&Set.of("PENDING","APPROVED").contains(state)&&r.getDeleteAt()!=null&&!r.getDeleteAt().isAfter(Instant.now()))state="EXPIRED";if(r!=null&&Set.of("APPROVED","PENDING").contains(state)){try{if(!reference(r.getUserId()).equals(r.getReferenceUrl()))state="PHOTO_CHANGED";}catch(ResponseStatusException missing){state="PHOTO_CHANGED";}}return r==null?null:new View(r.getId(),r.getUserId(),state,r.getChallenge(),r.getChallengeExpires(),r.getSubmittedAt(),r.getDeleteAt(),r.getNote(),r.getSelfieFile()!=null&&r.getDeleteAt()!=null&&r.getDeleteAt().isAfter(Instant.now()));}
 private User user(String email){var u=em.createQuery("select u from User u where u.email=:e",User.class).setParameter("e",email).getResultStream().findFirst().orElseThrow(()->fail(401,"로그인이 필요합니다."));if(!Set.of("ACTIVE","PENDING_REVIEW","REJECTED").contains(u.getStatus()))throw fail(403,"사용할 수 없는 계정입니다.");return u;}
 private String reference(Long user){return em.createQuery("select i.imageUrl from UserProfileImage i where i.userId=:u order by i.isMain desc,i.imageOrder",String.class).setParameter("u",user).setMaxResults(1).getResultStream().findFirst().orElseThrow(()->fail(409,"대표 프로필 사진을 먼저 등록해 주세요."));}
 @Transactional(readOnly=true) public View status(String email){var u=user(email);return em.createQuery("select r from SelfieReview r where r.userId=:u order by r.id desc",SelfieReview.class).setParameter("u",u.getId()).setMaxResults(1).getResultStream().map(this::view).findFirst().orElse(null);}
 @Transactional public View start(String email){var u=user(email);em.lock(u,LockModeType.PESSIMISTIC_WRITE);if(!u.isSelfieRequired()&&!Set.of("PENDING_REVIEW","REJECTED").contains(u.getStatus()))throw fail(403,"운영자 요청이 있을 때만 셀피를 제출할 수 있습니다.");reference(u.getId());var latest=em.createQuery("select r from SelfieReview r where r.userId=:u order by r.id desc",SelfieReview.class).setParameter("u",u.getId()).setMaxResults(1).getResultStream().findFirst().orElse(null);
  if(latest!=null&&"PENDING".equals(latest.getState())){if(latest.getDeleteAt()!=null&&latest.getDeleteAt().isAfter(Instant.now())&&reference(u.getId()).equals(latest.getReferenceUrl()))throw fail(409,"이미 셀피 심사 중입니다.");latest.setState("RETRY");}
  if(latest!=null&&"CAPTURE".equals(latest.getState())&&latest.getChallengeExpires().isAfter(Instant.now()))return view(latest);
  long count=em.createQuery("select count(r) from SelfieReview r where r.userId=:u and r.challenge is not null and r.createdAt>:since",Long.class).setParameter("u",u.getId()).setParameter("since",Instant.now().minus(Duration.ofDays(1))).getSingleResult();if(count>=3)throw fail(429,"셀피 촬영은 24시간 동안 3회까지 시작할 수 있습니다.");
  var r=new SelfieReview();r.setUserId(u.getId());r.setChallenge(List.of("얼굴 옆에 손가락 두 개로 V를 만들어 주세요.","손바닥을 펼쳐 얼굴 옆에 보여 주세요.","엄지를 세워 얼굴 옆에 보여 주세요.","검지 한 개를 펴서 얼굴 옆에 보여 주세요.","손가락 세 개를 펴서 얼굴 옆에 보여 주세요.","가볍게 주먹을 쥐고 얼굴 옆에 보여 주세요.").get(new java.security.SecureRandom().nextInt(6)));r.setChallengeExpires(Instant.now().plusSeconds(600));em.persist(r);return view(r);
 }
 @Transactional(readOnly=true) public View forUser(Long id){return em.createQuery("select r from SelfieReview r where r.userId=:u order by r.id desc",SelfieReview.class).setParameter("u",id).setMaxResults(1).getResultStream().map(this::view).findFirst().orElse(null);}
 @Transactional public void requireSignup(Long userId,boolean approved){
  em.find(User.class,userId,LockModeType.PESSIMISTIC_WRITE);
  var r=em.createQuery("select r from SelfieReview r where r.userId=:u order by r.id desc",SelfieReview.class).setParameter("u",userId).setMaxResults(1).getResultStream().findFirst().orElse(null);
  if(r==null||r.getConsentAt()==null||r.getSubmittedAt()==null||r.getDeleteAt()==null||!r.getDeleteAt().isAfter(Instant.now())||r.getPurgedAt()!=null||!Set.of("PENDING","APPROVED").contains(r.getState())||!reference(userId).equals(r.getReferenceUrl()))throw fail(409,"가입을 위해 필수 셀피 동의와 촬영 제출을 완료해 주세요. 대표 사진을 바꾸면 다시 촬영해야 합니다.");
  if(approved&&!"APPROVED".equals(r.getState()))throw fail(409,"셀피를 프로필 사진과 비교하고 수동 확인 완료로 처리한 뒤 가입을 승인해 주세요.");
 }
 private Path root()throws IOException {var p=Path.of(config.dir()==null?"uploads":config.dir()).toAbsolutePath().normalize().resolve("selfie-review");Files.createDirectories(p);return p.toRealPath();}
 private Path file(String name)throws IOException {if(name==null||!name.matches("[a-f0-9-]{36}\\.png"))throw fail(404,"사진을 찾을 수 없습니다.");return root().resolve(name);}
 private String save(byte[] bytes)throws IOException{String name=UUID.randomUUID()+".png";Files.write(file(name),bytes,StandardOpenOption.CREATE_NEW);return name;}
 @Transactional public View submit(String email,Long id,boolean consent,MultipartFile upload){var u=user(email);em.lock(u,LockModeType.PESSIMISTIC_WRITE);var r=em.find(SelfieReview.class,id,LockModeType.PESSIMISTIC_WRITE);if(r==null||!r.getUserId().equals(u.getId()))throw fail(404,"촬영 요청을 찾을 수 없습니다.");if(!u.isSelfieRequired()&&!Set.of("PENDING_REVIEW","REJECTED").contains(u.getStatus()))throw fail(403,"운영자 요청이 취소되었습니다.");if(!consent)throw fail(400,"셀피 수집·보관 동의가 필요합니다.");if(!"CAPTURE".equals(r.getState())||!r.getChallengeExpires().isAfter(Instant.now()))throw fail(409,"촬영 요청이 만료됐습니다. 다시 시작해 주세요.");if(upload==null||upload.isEmpty()||upload.getSize()>2*1024*1024)throw fail(400,"셀피는 2MB 이하로 촬영해 주세요.");
  String selfie=null,ref=null;
  try(var input=ImageIO.createImageInputStream(upload.getInputStream())){var readers=ImageIO.getImageReaders(input);if(!readers.hasNext())throw fail(400,"사진 형식을 확인해 주세요.");var reader=readers.next();java.awt.image.BufferedImage image;try{reader.setInput(input);int w=reader.getWidth(0),h=reader.getHeight(0);if(w<160||h<160||(long)w*h>2_000_000)throw fail(400,"셀피 해상도를 확인해 주세요.");image=reader.read(0);}finally{reader.dispose();}var output=new ByteArrayOutputStream();ImageIO.write(image,"png",output);
   String url=reference(u.getId());var original=ImageIO.read(media.path(url.substring("/uploads/".length())).toFile());if(original==null)throw fail(400,"대표 사진을 확인해 주세요.");var referenceBytes=new ByteArrayOutputStream();ImageIO.write(original,"png",referenceBytes);selfie=save(output.toByteArray());ref=save(referenceBytes.toByteArray());r.setSelfieFile(selfie);r.setReferenceFile(ref);r.setReferenceUrl(url);r.setConsentAt(Instant.now());r.setConsentVersion("ACTIVE".equals(u.getStatus())?"selfie-operator-request-2026-11-04":"selfie-signup-required-2026-11-04");r.setSubmittedAt(Instant.now());r.setDeleteAt(Instant.now().plus(Duration.ofDays(30)));r.setState("PENDING");
   final String a=selfie,c=ref;org.springframework.transaction.support.TransactionSynchronizationManager.registerSynchronization(new org.springframework.transaction.support.TransactionSynchronization(){public void afterCompletion(int status){if(status!=STATUS_COMMITTED)try{Files.deleteIfExists(file(a));Files.deleteIfExists(file(c));}catch(IOException ignored){}}});return view(r);
  }catch(IOException e){try{if(selfie!=null)Files.deleteIfExists(file(selfie));if(ref!=null)Files.deleteIfExists(file(ref));}catch(IOException ignored){}throw fail(500,"사진 저장에 실패했습니다.");}
 }
 @Transactional(readOnly=true) public List<View> list(int page){return em.createQuery("select r from SelfieReview r where r.submittedAt is not null order by r.id desc",SelfieReview.class).setFirstResult(Math.max(0,Math.min(page,10000))*30).setMaxResults(30).getResultList().stream().map(this::view).toList();}
 @Transactional(readOnly=true) public byte[] photo(Long id,boolean reference){var r=em.find(SelfieReview.class,id);if(r==null||r.getDeleteAt()==null||!r.getDeleteAt().isAfter(Instant.now())||r.getPurgedAt()!=null)throw fail(404,"보관 기간이 지난 사진입니다.");try{return Files.readAllBytes(file(reference?r.getReferenceFile():r.getSelfieFile()));}catch(IOException e){throw fail(404,"사진을 찾을 수 없습니다.");}}
 @Transactional public View decide(Long id,boolean approve,String note){var initial=em.find(SelfieReview.class,id);if(initial==null)throw fail(404,"촬영 요청을 찾을 수 없습니다.");var member=em.find(User.class,initial.getUserId(),LockModeType.PESSIMISTIC_WRITE);var latest=em.createQuery("select max(r.id) from SelfieReview r where r.userId=:u",Long.class).setParameter("u",initial.getUserId()).getSingleResult();if(!id.equals(latest))throw fail(409,"최신 셀피 요청만 심사할 수 있습니다.");var r=em.find(SelfieReview.class,id,LockModeType.PESSIMISTIC_WRITE);if(r==null||!"PENDING".equals(r.getState())||r.getDeleteAt()==null||!r.getDeleteAt().isAfter(Instant.now()))throw fail(409,"심사할 수 없는 요청입니다.");if(note!=null&&note.length()>1000)throw fail(400,"사유는 1000자 이하로 입력해 주세요.");if(!approve&&(note==null||note.isBlank()))throw fail(400,"보완 요청 사유를 입력해 주세요.");if(approve&&(note==null||note.isBlank()))note="셀피 확인 완료";if(approve&&!reference(r.getUserId()).equals(r.getReferenceUrl()))throw fail(409,"대표 사진이 변경됐습니다. 보완 요청 후 새 사진으로 다시 심사해 주세요.");r.setState(approve?"APPROVED":"RETRY");if(approve){member.setSelfieRequired(false);member.setSelfieRequestReason(null);}r.setNote(note);r.setReviewedAt(Instant.now());r.setDeleteAt(Instant.now().plus(Duration.ofDays(30)));inbox.add(r.getUserId(),"SELFIE:"+id,"셀피 심사 결과",approve?"셀피 수동 확인이 완료됐어요.":"다시 촬영해 주세요: "+note,"/selfie-required");return view(r);}
 @Transactional public void withdrawConsent(String email){var u=user(email);em.lock(u,LockModeType.PESSIMISTIC_WRITE);for(var r:em.createQuery("select r from SelfieReview r where r.userId=:u and r.purgedAt is null",SelfieReview.class).setParameter("u",u.getId()).setLockMode(LockModeType.PESSIMISTIC_WRITE).getResultList()){r.setDeleteAt(Instant.now());r.setState("WITHDRAWN");r.setNote("셀피 동의를 철회했습니다.");}}
 @Scheduled(fixedDelay=3600000) @Transactional public void purge(){for(var r:em.createQuery("select r from SelfieReview r where r.deleteAt<=:now and r.purgedAt is null",SelfieReview.class).setParameter("now",Instant.now()).setMaxResults(100).setLockMode(LockModeType.PESSIMISTIC_WRITE).getResultList()){try{if(r.getSelfieFile()!=null)Files.deleteIfExists(file(r.getSelfieFile()));if(r.getReferenceFile()!=null)Files.deleteIfExists(file(r.getReferenceFile()));r.setSelfieFile(null);r.setReferenceFile(null);r.setPurgedAt(Instant.now());if("PENDING".equals(r.getState()))r.setState("EXPIRED");}catch(IOException e){throw new IllegalStateException("Selfie cleanup failed; retry required",e);}}}
 private ResponseStatusException fail(int status,String text){return new ResponseStatusException(HttpStatus.valueOf(status),text);}
}
